import {withDefaultDiamondScale} from './default-scale.mjs';
import {presetSnapshot,createPresetId} from './preset-data.mjs';
import {presets,makeState} from './engine.mjs';
import {temperamentFromInput} from './temperament-input.mjs';
import {esc} from './ui.mjs';
const commaText=s=>s.commas==='custom mapping'?'':s.commas||'';
export function createPresetWorkspace({getStates,apply,refresh,notify,getJI=()=>undefined,request=fetch}){
 const chooseDefault=s=>withDefaultDiamondScale(s,notify,getJI(s));
 let items=[],status='loading',error='',busy=false,drafts=[null,null],deleteId=null;
 function draft(idx){const s=getStates()[idx];if(drafts[idx]?.source!==s&&drafts[idx]&&JSON.stringify([drafts[idx].source.name,drafts[idx].source.commas,drafts[idx].source.basis,drafts[idx].source.rows,drafts[idx].source.savedPresetId])===JSON.stringify([s.name,s.commas,s.basis,s.rows,s.savedPresetId]))drafts[idx].source=s;if(drafts[idx]?.source!==s)drafts[idx]={source:s,name:s.name,basis:s.basis.join('.'),commas:commaText(s),isNew:false,open:false};return drafts[idx];}
 async function api(url,options){const r=await request(url,options);let data;try{data=await r.json();}catch{throw Error('Preset storage is unavailable. Please retry.');}if(!r.ok)throw Error(data.error||'Could not access presets.');return data;}
 async function init(){status='loading';error='';refresh();try{const data=await api('/api/presets');items=data.presets;status='ready';}catch(e){status='error';error=e.message;}refresh();}
 function render(idx){const s=getStates()[idx],d=draft(idx),current=items.find(p=>p.id===s.savedPresetId),disabled=busy||status!=='ready',selected=d.isNew?'new':current?'saved:'+current.id:!s.savedPresetId&&presets[s.key]?'builtin:'+s.key:'current';return `<div class="temperament-choice"><label>Temperament<select data-saved-preset="${idx}" ${busy?'disabled':''}><option value="new" ${selected==='new'?'selected':''}>+ New from commas…</option>${selected==='current'?`<option value="current" selected>${esc(s.name)} · unsaved</option>`:''}<optgroup label="Built-in temperaments">${Object.entries(presets).sort(([,a],[,b])=>a.name.localeCompare(b.name,undefined,{numeric:true})).map(([key,p])=>`<option value="builtin:${key}" ${selected==='builtin:'+key?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup><optgroup label="Saved temperaments">${items.length?items.map(p=>`<option value="saved:${esc(p.id)}" ${selected==='saved:'+p.id?'selected':''}>${esc(p.name)} [${p.state.n}]</option>`).join(''):`<option disabled>${status==='loading'?'Loading…':status==='error'?'Unavailable · retry below':'No saved temperaments yet'}</option>`}</optgroup></select></label>
 <details class="temperament-editor" data-temp-editor="${idx}" ${d.open?'open':''}><summary>${d.isNew?'New temperament':'Edit commas & manage preset'}</summary><div class="temperament-editor-fields"><label>Name<input data-preset-name="${idx}" maxlength="80" value="${esc(d.name)}" placeholder="Temperament name" ${busy?'disabled':''}></label><label>Prime basis<input data-preset-basis="${idx}" value="${esc(d.basis)}" placeholder="2.3.5" ${busy?'disabled':''}></label></div><label class="temperament-editor-commas">Commas<input data-preset-commas="${idx}" value="${esc(d.commas)}" placeholder="81/80 or 55/54, 64/63, 100/99" ${busy?'disabled':''}></label><div class="panelactions"><button data-user-preset="generate" data-s="${idx}" ${busy?'disabled':''}>Apply commas</button><button data-user-preset="save" data-s="${idx}" class="primary" ${disabled?'disabled':''}>${busy?'Working…':current&&!d.isNew?'Save changes':'Save preset'}</button>${current&&!d.isNew?`<button data-user-preset="new" data-s="${idx}" ${disabled?'disabled':''}>Save as new</button><button data-user-preset="delete" data-s="${idx}" ${disabled?'disabled':''}>Delete preset</button>`:''}</div>${deleteId===current?.id?`<div class="preset-delete" role="alert">Delete saved preset “${esc(current.name)}”?<div class="panelactions"><button data-user-preset="confirm-delete" data-s="${idx}" ${busy?'disabled':''}>Delete</button><button data-user-preset="cancel-delete" ${busy?'disabled':''}>Cancel</button></div></div>`:''}${error?`<p class="notice" role="status">${esc(error)}</p>`:''}<button class="quiet" data-user-preset="refresh" ${busy?'disabled':''}>Refresh saved list</button></details></div>`;}
 function input(el){const field=el.dataset.presetName!==undefined?'name':el.dataset.presetCommas!==undefined?'commas':el.dataset.presetBasis!==undefined?'basis':null;if(!field)return false;const idx=Number(el.dataset['preset'+field[0].toUpperCase()+field.slice(1)]);draft(idx)[field]=el.value;return true;}
 function toggle(el){if(el.dataset.tempEditor===undefined)return;draft(Number(el.dataset.tempEditor)).open=el.open;}
 function receiveCommas(idx,basis,list){const d=draft(idx);Object.assign(d,{name:'',commas:list.map(t=>t.label).join(', '),basis:basis.join('.'),isNew:true,open:true});deleteId=null;refresh();}
 function change(el){if(el.dataset.savedPreset===undefined)return false;const idx=Number(el.dataset.savedPreset),value=el.value;deleteId=null;error='';if(value==='new'){Object.assign(draft(idx),{name:'',commas:'',isNew:true,open:true});refresh();return true;}if(value==='current')return true;try{if(value.startsWith('builtin:')){drafts[idx]=null;apply(idx,chooseDefault(makeState(value.slice(8))));return true;}const p=items.find(p=>p.id===value.replace(/^saved:/,''));if(p){drafts[idx]=null;apply(idx,chooseDefault({...presetSnapshot(p.name,p.state),savedPresetId:p.id}));notify(`Loaded ${p.name}.`);}}catch(e){notify(e.message);}return true;}
 function materialize(idx){const s=getStates()[idx],d=draft(idx),changed=d.isNew||d.commas.trim()!==commaText(s).trim()||d.basis!==s.basis.join('.');if(!changed)return {...s,name:d.name.trim()||s.name};const next=chooseDefault(temperamentFromInput(d.basis,d.commas,s));next.name=d.name.trim()||next.name;if(!d.isNew&&s.savedPresetId)next.savedPresetId=s.savedPresetId;return next;}
 function generate(idx){try{const s=materialize(idx);drafts[idx]={source:s,name:s.name,basis:s.basis.join('.'),commas:commaText(s),isNew:false,open:true};apply(idx,s);notify('Temperament generated from commas.');}catch(e){error=e.message;notify(e.message);refresh();}}
 async function save(idx,asNew){if(busy||status!=='ready')return;let snapshot,source;const d=draft(idx);try{source=materialize(idx);snapshot=presetSnapshot(d.name.trim()||source.name,source);}catch(e){error=e.message;notify(e.message);refresh();return;}
 const old=asNew||d.isNew?null:items.find(p=>p.id===getStates()[idx].savedPresetId),id=old?.id||createPresetId(),before=JSON.stringify(getStates()[idx]);busy=true;error='';refresh();
 try{const data=await api('/api/presets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:snapshot.name,state:snapshot,revision:old?.revision||0})}),p=data.preset;items=[...items.filter(v=>v.id!==id),p].sort((a,b)=>a.name.localeCompare(b.name));busy=false;if(JSON.stringify(getStates()[idx])===before){drafts[idx]=null;apply(idx,{...snapshot,savedPresetId:id});}notify(`Saved ${p.name}.`);}catch(e){error=e.message;notify(e.message);}finally{busy=false;refresh();}}
 async function remove(idx){const p=items.find(p=>p.id===deleteId);if(busy||!p||getStates()[idx].savedPresetId!==p.id)return;busy=true;error='';refresh();try{await api('/api/presets/'+p.id+'?revision='+p.revision,{method:'DELETE'});items=items.filter(v=>v.id!==p.id);deleteId=null;if(getStates()[idx].savedPresetId===p.id){const s={...getStates()[idx],key:'custom'};delete s.savedPresetId;drafts[idx]=null;apply(idx,s);}notify(`Deleted ${p.name}.`);}catch(e){error=e.message;notify(e.message);}finally{busy=false;refresh();}}
 function click(b){const action=b.dataset.userPreset;if(!action)return false;const idx=Number(b.dataset.s);if(action==='refresh')void init();else if(action==='save'||action==='new')void save(idx,action==='new');else if(action==='generate')generate(idx);else if(action==='delete'){deleteId=getStates()[idx].savedPresetId;draft(idx).open=true;refresh();}else if(action==='cancel-delete'){deleteId=null;refresh();}else if(action==='confirm-delete')void remove(idx);return true;}
 return {init,render,input,toggle,receiveCommas,change,click,catalog:()=>({items,status,error})};
}
